// src/services/feed/EventAvailabilityPreviewService.ts
// 🔴 READ-MODEL
// NÃO usar para decisões.
// Fonte canônica: unified-availability.service.ts
// 🔴 CRÍTICO: Preview READ-ONLY, nunca reserva ou bloqueia slots
import { runQueriesWithTenant } from '@core/db';

export interface AvailabilityPreview {
  eventId: string;
  nextAvailableSlots: Array<{
    start: string; // ISO 8601
    end: string; // ISO 8601
  }>;
  timezone: string;
}

interface EventRow {
  id: string;
  schedule_id: string | null;
  timezone: string;
}

interface SlotRow {
  slot_id: string;
  start_time: Date;
  end_time: Date;
}

export class EventAvailabilityPreviewService {
  /**
   * Busca preview de disponibilidade (READ-ONLY)
   * 🔴 NUNCA reserva, apenas exibe próximos slots disponíveis
   */
  async getAvailabilityPreview(
    eventId: string,
    tenantId: string
  ): Promise<AvailabilityPreview | null> {
    // 1. Buscar evento e schedule_id
    const eventRows = await runQueriesWithTenant<EventRow>(tenantId, {
      text: `
        SELECT id, schedule_id, timezone
        FROM events
        WHERE id = $1
      `,
      values: [eventId],
    });

    if (eventRows.length === 0) {
      return null;
    }

    const event = eventRows[0];
    const timezone = event.timezone || 'America/Sao_Paulo';

    // 2. Se não tem schedule_id, retornar apenas timezone
    if (!event.schedule_id) {
      return {
        eventId,
        nextAvailableSlots: [],
        timezone,
      };
    }

    // 3. Buscar próximos 3 slots disponíveis (READ-ONLY)
    const slotRows = await runQueriesWithTenant<SlotRow>(tenantId, {
      text: `
        SELECT slot_id, start_time, end_time
        FROM schedule_slots
        WHERE schedule_id = $1
          AND status = 'available'
          AND start_time >= NOW()
        ORDER BY start_time ASC
        LIMIT 3
      `,
      values: [event.schedule_id],
    });

    const nextAvailableSlots = slotRows.map((slot) => ({
      start: slot.start_time.toISOString(),
      end: slot.end_time.toISOString(),
    }));

    return {
      eventId,
      nextAvailableSlots,
      timezone,
    };
  }
}



























